def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    pairing = zip(string.ascii_lowercase, string.ascii_uppercase)
    result = []
    for char in string:
        for lower, upper in pairing:
            if char == lower:
                result.append(upper)
                break
