T = TypeVar('T')

class LinkedList(Generic[T]):
    def __init__(self, head: T = None, tail: LinkedList[T] = None):
        self.head = head
        self.tail = tail

def fib(n: int) -> LinkedList[int]:
    """Return n-th Fibonacci number as a linked list.
    If n is not a valid index, return an empty linked list.
    """
    if n == 1:
        return LinkedList(head=1)
    elif n == 2:
        return LinkedList(head=1, tail=LinkedList(head=1))
    else:
        fib_list = [1, 1]
        for i in range(2, n):
            temp = fib_list[i - 1] + fib_list[i - 2]
            fib_list.append(temp)
        return LinkedList(*reversed(fib_list[:n]))
